html:
{#- Pesanan ke supplier, dicetak dari Purchase Order -#}

{%- set pt = split_payment_terms(doc.payment_terms_template or doc.tc_name) -%}
{%- set currency = doc.currency -%}
{%- set contact_numbers = [doc.contact_mobile, doc.contact_phone] | select | unique | list -%}
{%- set salutation = frappe.db.get_value("Contact", doc.contact_person, "salutation") if doc.contact_person else None -%}
{%- set project_name = (frappe.db.get_value("Project", doc.project, "project_name") or doc.project) if doc.get("project") else "" -%}

<style>
	/* kotak Order To & Delivered To, judulnya nempel di garis atas (sama kayak Delivery Order).
	   Dibatesin ke .parties: blok alamat company di kop juga pakai class `box`. */
	.vic-pf .parties { width: 100%; margin-top: 14px; table-layout: fixed; }
	.vic-pf .parties > tbody > tr > td { vertical-align: top; }
	.vic-pf .parties .left { width: 52%; padding-right: 30px !important; }
	.vic-pf .parties .box {
		border: 1px solid #000;
		border-radius: 3px;
		padding: 9px 10px 8px;
		min-height: 62px;
		position: relative;
	}
	.vic-pf .parties .right .box { min-height: 0; margin-top: 12px; }
	.vic-pf .parties .box .cap {
		position: absolute;
		top: -7px;
		left: 9px;
		background: #fff;
		padding: 0 4px;
		font-size: 9px;
	}
	.vic-pf .parties .box .name { font-weight: 700; }
	.vic-pf .parties .box .addr { font-size: 10px; }
	/* isian field Order To / Delivered To diketik bebas, baris barunya ikut kecetak */
	.vic-pf .parties .box .free-text { white-space: pre-line; }
	/* selebar kolom kanan - kalau otomatis, tanggal Delivery Time kepotong ke baris baru */
	.vic-pf .po-terms { width: 100%; }
	.vic-pf .po-terms .lbl { width: 85px; }
	.vic-pf .po-terms .sep { width: 12px; }
	/* terbilang di kiri, total di kanan - satu baris */
	.vic-pf .summary { width: 100%; margin-top: 6px; table-layout: fixed; }
	.vic-pf .summary > tbody > tr > td { vertical-align: top; }
	.vic-pf .summary .words { width: 55%; padding-right: 20px !important; font-size: 10px; }
	.vic-pf .summary .totals { margin-top: 0; }
	/* blok total cuma selebar kolom kanan, jadi kolom angkanya dilebarin dari bawaan (18%) */
	.vic-pf .summary .totals .money { width: 42%; }
	/* Note di bawah item terakhir: Terms and Conditions itu HTML dari editor - paragrafnya jangan
	   nambah jarak; Penalty Clause teks biasa, baris barunya ikut kecetak */
	.vic-pf .items tr.note .note-item p { margin: 0; }
	.vic-pf .items tr.note .penalty { white-space: pre-line; }
</style>

<div class="vic-pf">
	{%- include "vic_addon/templates/print_formats/vic_letterhead.html" -%}

	<div class="title-wrap">
		<div class="title-block">
			<div class="doc-title">PURCHASE ORDER</div>
			<table class="meta">
				<tr>
					<td class="lbl">Order No.</td>
					<td class="sep">:</td>
					<td>{{ doc.name }}</td>
				</tr>
				<tr>
					<td class="lbl">Date</td>
					<td class="sep">:</td>
					<td>{{ frappe.utils.formatdate(doc.transaction_date, "MMMM d, yyyy") }}</td>
				</tr>
			</table>
		</div>
	</div>

	<table class="parties">
		<tr>
			<td class="left">
				<div class="box">
					<span class="cap">Order To</span>
					<div class="name">{{ doc.supplier_name or doc.supplier }}</div>
					{#- field Order To duluan (keisi dari Supplier Address, bisa diedit); kosong -> alamat supplier -#}
					{%- if doc.get("custom_order_to") %}
						<div class="addr free-text">{{ doc.custom_order_to }}</div>
					{%- elif doc.address_display %}
						<div class="addr">{{ doc.address_display }}</div>
					{%- endif %}
					{%- if contact_numbers %}<div>{{ contact_numbers | join(" / ") }}</div>{% endif %}
					{%- if doc.contact_display %}<div>{{ [salutation, doc.contact_display] | select | join(" ") }}</div>{% endif %}
				</div>
			</td>
			<td class="right">
				<table class="po-terms">
					<tr>
						<td class="lbl">Payment Terms</td>
						<td class="sep">:</td>
						<td>{{ pt.header }}</td>
					</tr>
					<tr>
						<td class="lbl">Delivery Time</td>
						<td class="sep">:</td>
						{#- field Delivery Time duluan; kosong -> tanggal Required By -#}
						<td>{{ doc.get("custom_delivery_time") or (frappe.utils.formatdate(doc.schedule_date, "MMMM d, yyyy") if doc.schedule_date else "") }}</td>
					</tr>
				</table>
				<div class="box">
					<span class="cap">Delivered To</span>
					{#- field Delivered To duluan (bisa diubah setelah submit, buat dropship); kosong -> alamat
					    pengiriman PO, nama alamatnya, lalu nama project -#}
					{%- if doc.get("custom_delivered_to") %}
						<div class="addr free-text">{{ doc.custom_delivered_to }}</div>
					{%- else %}
						<div class="addr">{{ doc.shipping_address_display or doc.shipping_address or project_name or "" }}</div>
					{%- endif %}
				</div>
			</td>
		</tr>
	</table>

	<table class="items">
		<thead>
			<tr>
				<th style="width: 7%">Item</th>
				<th class="left" style="width: 43%">Description</th>
				<th style="width: 14%">Qty</th>
				<th style="width: 18%">Unit Price<div>{{ currency }}</div></th>
				<th style="width: 18%">Total Price<div>{{ currency }}</div></th>
			</tr>
		</thead>
		<tbody>
			{%- set ns = namespace(no = 0) %}
			{%- for header, rows in group_items_by_header(doc.items) %}
				{%- if header %}
					{#- judul kelompok mulai di kolom Description, kolom sebelumnya dikosongin -#}
					<tr class="group pengiriman"><td></td><td class="text" colspan="4">{{ header }}</td></tr>
				{%- endif %}
				{%- for item in rows %}
					{%- set ns.no = ns.no + 1 %}
					{%- set size = frappe.db.get_value("Item", item.item_code, "custom_size") %}
					{%- set qty = item.qty | float %}
					<tr>
						<td class="num">{{ ns.no }}</td>
						<td class="text">
							<div class="desc">{{ get_item_description(item) }}</div>
							{%- if size %}<div>Size : {{ size }}</div>{% endif %}
						</td>
						<td class="qty">{{ qty | int if qty == qty | round(0) else "%.2f" | format(qty) }} {{ item.uom }}</td>
						<td class="money">{{ frappe.utils.fmt_money(item.rate) }}</td>
						<td class="money">{{ frappe.utils.fmt_money(item.amount) }}</td>
					</tr>
				{%- endfor %}
			{%- endfor %}

			{#- Note jadi baris terakhir tabel, nempel di kolom Description: Terms and Conditions PO,
			    terus Penalty Clause di bawahnya. Editor sering nyimpen tag kosong (`<p></p>`) waktu
			    isinya dihapus - yang kayak gitu dianggap kosong. -#}
			{%- set terms = doc.terms if frappe.utils.strip_html(doc.terms or "").replace("&nbsp;", " ").strip() else "" %}
			{%- set penalty = (doc.get("custom_penalty_clause") or "").strip() %}
			{#- Term pembayaran > 20 karakter: di sini ditulis "Lihat di Note", teks lengkapnya jadi poin pertama
	    Note di akhir tabel item (split_payment_terms di vic/print_utils.py) -#}
			{%- if pt.note or terms or penalty %}
				<tr class="note">
					<td></td>
					<td class="text">
						<div>Note:</div>
						{%- if pt.note %}<div class="note-item">Payment Terms : {{ pt.note }}</div>{% endif %}
						{%- if terms %}<div class="note-item">{{ terms }}</div>{% endif %}
						{%- if penalty %}<div class="note-item penalty">{{ penalty | e }}</div>{% endif %}
					</td>
					<td colspan="3"></td>
				</tr>
			{%- endif %}
		</tbody>
	</table>

	{#- WAPU: PPN dipungut pembeli, jadi tabel pajaknya kosong. Kalau Show VAT for WAPU dicentang,
	    PPN 11% tetap dicetak (dihitung dari Net Total) dan ikut dijumlah ke Grand Total + terbilangnya
	    di kertas - dokumennya sendiri gak berubah. Kalau ada baris PPN di tabel, yang dipakai baris itu. -#}
	{%- set vat_rows = doc.taxes | rejectattr("is_tax_withholding_account") | selectattr("add_deduct_tax", "ne", "Deduct") | list %}
	{%- set wapu_vat = frappe.utils.flt((doc.net_total | float) * 0.11, 2) if (doc.get("custom_show_vat_for_wapu") and not vat_rows) else 0 %}
	{#- Rounded Total kalau dipakai (lihat get_grand_total); VAT WAPU ikut dijumlah lalu dibulatin -#}
	{%- set grand_total = get_grand_total(doc, (doc.grand_total | float) + wapu_vat) if wapu_vat else get_grand_total(doc) %}
	{%- set in_words = frappe.utils.money_in_words(grand_total, doc.currency) if wapu_vat else doc.in_words %}
	<table class="summary">
		<tr>
			<td class="words">
				{%- if in_words %}
					<div>in Words :</div>
					<div>{{ in_words | upper }}</div>
				{%- endif %}
			</td>
			<td>
			<table class="totals">
					<tr>
						<td class="lbl">Total Price</td>
						<td class="money">{{ frappe.utils.fmt_money(doc.total) }}</td>
					</tr>
					{#- PPN selalu dicetak di bawah Total Price, labelnya "PPN <rate>%" (bukan deskripsi akunnya);
					    PO tanpa PPN tetap kecetak "PPN 11%" senilai 0, ngikut formulir. Baris pajak lain (PPh,
					    potongan) dicetak pakai deskripsinya. -#}
					{%- set other_rows = doc.taxes | reject("in", vat_rows) | list %}
					{%- if vat_rows %}
						{%- for tax in vat_rows %}
							<tr>
								<td class="lbl">PPN {{ "%g" | format(tax.rate | float) if tax.rate else 11 }}%</td>
								<td class="money">{{ frappe.utils.fmt_money(tax.tax_amount) }}</td>
							</tr>
						{%- endfor %}
					{%- else %}
						<tr>
							<td class="lbl">PPN 11%</td>
							<td class="money">{{ frappe.utils.fmt_money(wapu_vat) }}</td>
						</tr>
					{%- endif %}
					{%- for tax in other_rows %}
						<tr>
							<td class="lbl">{{ tax.description }}</td>
							<td class="money">{{ frappe.utils.fmt_money(tax.tax_amount) }}</td>
						</tr>
					{%- endfor %}
					<tr class="grand">
						<td class="lbl">Grand Total</td>
						<td class="money">{{ frappe.utils.fmt_money(grand_total) }}</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="sign">
		<tr>
			<td style="width: 50%">
				<div class="role">Best regards,</div>
				{#- field Best Regards duluan; kosong -> nama user yang bikin -#}
				<div>{{ doc.get("custom_best_regards") or frappe.db.get_value("User", doc.owner, "full_name") or "" }}</div>
				<div>Director</div>
			</td>
			<td style="width: 50%">
				<div class="role">Supplier Approved</div>
				<div>{{ doc.contact_display or doc.supplier_name or doc.supplier }}</div>
			</td>
		</tr>
	</table>

	{#- Keterangan warna salinan, sama persis kayak formulir yang selama ini dipakai. Ditaruh di
	    footer halaman (pojok kiri bawah) biar ikut kecetak di tiap lembar, bukan cuma nempel di
	    bawah isi lembar terakhir. -#}
	{%- set vic_footer_note = ["Putih = Supplier", "Merah = Purchasing", "Kuning = Accounting", "Hijau = Finance"] -%}
	{%- include "vic_addon/templates/print_formats/vic_footer.html" -%}
</div>
